import os
import subprocess

# This code attempts to probe user namespace info and try unshare syscall for user namespace.

def check_user_namespace():
    try:
        with open('/proc/self/ns/user', 'r') as f:
            ns = f.read()
        print("User namespace info:", ns)
    except Exception as e:
        print("Failed to read user namespace info:", str(e))


def try_unshare_user_namespace():
    # Attempt to run `unshare` command to create new user namespace and run id inside it.
    try:
        result = subprocess.run(['unshare', '--user', '--map-root-user', 'id'], capture_output=True, text=True)
        if result.returncode == 0:
            print("Unshare user namespace succeeded:", result.stdout.strip())
        else:
            print("Unshare user namespace failed:", result.stderr.strip())
    except Exception as e:
        print("Error executing unshare user namespace:", str(e))


# Run the tests
check_user_namespace()
try_unshare_user_namespace()

